#!/bin/bash
# Rex appearance settings. Generated by save-defaults.sh, so edit Rex's
# settings and rerun that script instead of editing this file.
# Quit Rex before running this, then reopen it.
set -euo pipefail
domain="${REX_DEFAULTS_DOMAIN:-com.superlogical.rex}"

defaults write "$domain" Workspace.darkThemeID -string neon-arcade
defaults write "$domain" Workspace.lightThemeID -string merino-light
defaults write "$domain" Workspace.terminalFontName -string 0xProto\ Nerd\ Font\ Mono
defaults write "$domain" Workspace.terminalFontPointSize -float 16
defaults write "$domain" Workspace.interfaceStyle -string blendTheme
defaults write "$domain" Workspace.tabStyle -string vertical
defaults write "$domain" Workspace.tabIconTintMode -string off
defaults write "$domain" Workspace.sidebarPosition -string left
defaults write "$domain" Workspace.sidebarShowsActivity -bool false
defaults write "$domain" Workspace.paneDensity -string comfortable
defaults write "$domain" Workspace.inactivePaneFadeMode -string both
defaults write "$domain" Workspace.usesStandardInactiveWindowPaneStyles -bool true
defaults write "$domain" Workspace.animationStyle -string snappy
